# 04_external_SCC_validation.R
# Apply the fixed five-marker model to an independent supplied SCC RPPA cohort.
suppressPackageStartupMessages({library(readr);library(dplyr)})
OUT<-"results/validation/external_SCC";dir.create(OUT,recursive=TRUE,showWarnings=FALSE);MODEL_FILE<-"results/classifier/five_marker/five_marker_elastic_net_model.rds";INPUT<-Sys.getenv("EXTERNAL_SCC_RPPA_FILE","data/external/external_SCC_RPPA.csv");MARKERS<-c("ZAP-70","EVI1","EPPK1","ANNEXIN1","CD171")
if(!file.exists(MODEL_FILE))stop("Missing fitted model: ",MODEL_FILE);if(!file.exists(INPUT))stop("Missing external cohort: ",INPUT);obj<-readRDS(MODEL_FILE);d<-read_csv(INPUT,show_col_types=FALSE);id<-intersect(c("Patient","Sample","sample_id"),names(d))[1];if(is.na(id))stop("External cohort needs a sample identifier");names(d)[names(d)==id]<-"Patient";if(!all(MARKERS%in%names(d)))stop("Missing markers: ",paste(setdiff(MARKERS,names(d)),collapse=", "));z<-as.matrix(d[,MARKERS]);z<-sweep(z,2,obj$scale_center,"-");z<-sweep(z,2,obj$scale_scale,"/");pr<-as.numeric(predict(obj$model,newx=z,type="response"));o<-d%>%select(Patient)%>%mutate(keratinizing_probability=pr,molecular_state=case_when(pr<=.35~"Nonkeratinizing-like",pr>=.65~"Keratinizing-like",TRUE~"Indeterminate"));if("pathology_group"%in%names(d))o<-o%>%mutate(pathology_group=d$pathology_group,label=case_when(pathology_group%in%c("SCC-K","Keratinizing")~1,pathology_group%in%c("SCC-NK","Nonkeratinizing")~0,TRUE~NA_real_));write_csv(o,file.path(OUT,"external_SCC_five_marker_predictions.csv"));write_csv(count(o,molecular_state),file.path(OUT,"external_SCC_state_counts.csv"))
